import java.util.*;
interface NotificationChannel {String send(Student s,Notice n);}
class EmailChannel implements NotificationChannel {public String send(Student s,Notice n){return "[Email → "+s.name+"] "+n.title;}}
class SmsChannel implements NotificationChannel {public String send(Student s,Notice n){return "[SMS → "+s.name+"] "+n.title;}}
class AppChannel implements NotificationChannel {public String send(Student s,Notice n){return "[App → "+s.name+"] "+n.title;}}
class Student {final String name,department;final List<NotificationChannel> channels=new ArrayList<>();Student(String n,String d){name=n;department=d;}void prefer(NotificationChannel c){if(c==null)throw new IllegalArgumentException();channels.add(c);}}
class Notice {final String title;final Set<String> departments;Notice(String t,List<String>d){if(t==null||t.trim().isEmpty()||d==null||d.isEmpty())throw new IllegalArgumentException("At least one target department is required");title=t;departments=new LinkedHashSet<>(d);if(departments.contains(null)||departments.isEmpty())throw new IllegalArgumentException("At least one target department is required");}}
class NoticeBoard {final List<Student> students=new ArrayList<>();void register(Student s){if(s==null)throw new IllegalArgumentException();students.add(s);}List<String> post(Notice n){List<String> out=new ArrayList<>();for(Student s:students)if(n.departments.contains(s.department))for(NotificationChannel c:s.channels)out.add(c.send(s,n));return out;}}
public class Main {public static void main(String[]args){Student asha=new Student("Asha","CSE");asha.prefer(new EmailChannel());asha.prefer(new AppChannel());Student ravi=new Student("Ravi","ECE");ravi.prefer(new SmsChannel());NoticeBoard b=new NoticeBoard();b.register(asha);b.register(ravi);Notice n1=new Notice("Lab Closed Tomorrow",Arrays.asList("CSE"));System.out.println("Notice 'Lab Closed Tomorrow' posted to CSE.");for(String x:b.post(n1))System.out.println(x);Notice n2=new Notice("Fee Deadline Extended",Arrays.asList("CSE","ECE"));System.out.println("Notice 'Fee Deadline Extended' posted to CSE, ECE.");for(String x:b.post(n2))System.out.println(x);try{new Notice("Sports Day",Collections.emptyList());}catch(IllegalArgumentException e){System.out.println("Cannot post notice: At least one target department is required.");}}}